// Every page under /demos/ (demos/**/index.html, generated by scripts/demo-pages.ts). #root's data-page says which
// one; each loads as its own chunk. Same global styles and service worker start as the home page (src/main.tsx).
import './styles/reset.css'
import './styles/fonts.css'
import './styles/base.css'

import { lazy, StrictMode, Suspense } from 'react'
import { createRoot } from 'react-dom/client'
import { CONCEPTS } from './demos/concepts/index.ts'
import { startServiceWorker } from './telemetry/serviceWorker'

const root = document.getElementById('root')
if (!root) throw new Error('Missing #root element')
const key = root.dataset.page ?? 'index'

// The circuit breaker lived at /demos/#fault-lab before it had a page of its own.
if (key === 'index' && window.location.hash === '#fault-lab') {
  window.location.replace(`/demos/circuit-breaker/${window.location.search}`)
}

startServiceWorker()

const DemosIndex = lazy(() => import('./demos/pages/DemosIndex').then((m) => ({ default: m.DemosIndex })))
const CircuitBreakerPage = lazy(() =>
  import('./demos/pages/CircuitBreakerPage').then((m) => ({ default: m.CircuitBreakerPage })),
)
const SimulatedDemoPage = lazy(() =>
  import('./demos/pages/SimulatedDemoPage').then((m) => ({ default: m.SimulatedDemoPage })),
)

function Page() {
  if (key === 'index') return <DemosIndex />
  if (key === 'circuit-breaker') return <CircuitBreakerPage />
  const def = CONCEPTS.find((concept) => concept.slug === key)
  if (!def) throw new Error(`No demo for data-page="${key}"`)
  return <SimulatedDemoPage def={def} />
}

createRoot(root).render(
  <StrictMode>
    <Suspense>
      <Page />
    </Suspense>
  </StrictMode>,
)
